SELECT t.*,
       c.customer_nickname as customer_name,
       c.customer_phone as customer_phone,
       a.agent_name as agent_name,
       h.house_title as house_title,
       h.house_address as house_address
FROM h_transaction t
LEFT JOIN sys_customer c ON t.customer_id = c.customer_id
LEFT JOIN sys_agent a ON t.agent_id = a.agent_id
LEFT JOIN h_house h ON t.house_id = h.house_id


        AND t.customer_id = #{customerId}


        AND t.agent_id = #{agentId}


        AND t.house_id = #{houseId}


        AND t.transaction_status = #{status}


ORDER BY t.transaction_create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM h_transaction t


        AND t.customer_id = #{customerId}


