INSERT INTO h_transaction (
    house_id, customer_id, agent_id, viewing_id, transaction_no,
    transaction_final_price, transaction_deposit, transaction_payment_method, transaction_contract_url, transaction_deal_date,
    transaction_status, transaction_remark
) VALUES (
    #{houseId}, #{customerId}, #{agentId}, #{viewingId}, #{transactionNo},
    #{finalPrice}, #{deposit}, #{paymentMethod}, #{contractUrl}, #{dealDate},
    #{status}, #{remark}
)

mapper.update:
UPDATE h_transaction
transaction_final_price = #{finalPrice}, transaction_deposit = #{deposit}, transaction_payment_method = #{paymentMethod}, transaction_contract_url = #{contractUrl}, transaction_deal_date = #{dealDate}, transaction_status = #{status}, transaction_status_history = #{statusHistory}, transaction_remark = #{remark},
WHERE transaction_id = #{id}

mapper.select:
SELECT COALESCE(SUM(transaction_final_price), 0) FROM h_transaction t


        AND t.agent_id = #{agentId}


        AND t.transaction_status = #{status}


        AND t.transaction_deal_date >= #{startDate}


        AND t.transaction_deal_date <= #{endDate}

SELECT h.house_province AS province, h.house_city AS city, h.house_district AS district, COUNT(*) AS transactionCount, COALESCE(ROUND(SUM(t.transaction_final_price), 2), 0) AS salesAmount, COALESCE(ROUND(AVG(t.transaction_final_price), 2), 0) AS averagePrice, COALESCE(ROUND(AVG( CASE WHEN h.house_unit_price IS NOT NULL AND h.house_unit_price > 0 THEN h.house_unit_price WHEN h.house_area IS NOT NULL AND h.house_area > 0 THEN (h.house_price * 10000 / h.house_area) ELSE NULL END ), 2), 0) AS averageUnitPrice FROM h_transaction t INNER JOIN h_house h ON t.house_id = h.house_id WHERE t.transaction_status = 3
AND COALESCE(t.transaction_deal_date, DATE(t.transaction_update_time)) >= DATE_FORMAT(DATE_SUB(CURRENT_DATE(), INTERVAL #{offsetMonths} MONTH), '%Y-%m-01')
AND h.house_province IS NOT NULL AND h.house_province != '' AND h.house_district IS NOT NULL AND h.house_district != '' GROUP BY h.house_province, h.house_city, h.house_district ORDER BY salesAmount DESC, transactionCount DESC LIMIT #{limit}

SELECT a.agent_id AS agentId, a.agent_name AS agentName, a.agent_company AS company, a.agent_avatar AS avatar, COUNT(*) AS transactionCount, COALESCE(ROUND(SUM(t.transaction_final_price), 2), 0) AS salesAmount, COALESCE(ROUND(AVG(t.transaction_final_price), 2), 0) AS averagePrice FROM h_transaction t INNER JOIN sys_agent a ON t.agent_id = a.agent_id WHERE t.transaction_status = 3
AND COALESCE(t.transaction_deal_date, DATE(t.transaction_update_time)) >= DATE_FORMAT(DATE_SUB(CURRENT_DATE(), INTERVAL #{offsetMonths} MONTH), '%Y-%m-01')
GROUP BY a.agent_id, a.agent_name, a.agent_company, a.agent_avatar ORDER BY salesAmount DESC, transactionCount DESC LIMIT #{limit}

SELECT a.agent_company AS company, COUNT(*) AS transactionCount, COALESCE(ROUND(SUM(t.transaction_final_price), 2), 0) AS salesAmount, COALESCE(ROUND(AVG(t.transaction_final_price), 2), 0) AS averagePrice, COUNT(DISTINCT a.agent_id) AS agentCount FROM h_transaction t INNER JOIN sys_agent a ON t.agent_id = a.agent_id WHERE t.transaction_status = 3 AND a.agent_company IS NOT NULL AND a.agent_company != ''
AND COALESCE(t.transaction_deal_date, DATE(t.transaction_update_time)) >= DATE_FORMAT(DATE_SUB(CURRENT_DATE(), INTERVAL #{offsetMonths} MONTH), '%Y-%m-01')
GROUP BY a.agent_company ORDER BY salesAmount DESC, transactionCount DESC LIMIT #{limit}

SELECT h.house_province AS province, h.house_city AS city, h.house_district AS district, COUNT(*) AS transactionCount, COALESCE(ROUND(SUM(t.transaction_final_price), 2), 0) AS salesAmount, COALESCE(ROUND(AVG(t.transaction_final_price), 2), 0) AS averagePrice FROM h_transaction t INNER JOIN h_house h ON t.house_id = h.house_id WHERE t.transaction_status = 3 AND t.agent_id = #{agentId}
AND COALESCE(t.transaction_deal_date, DATE(t.transaction_update_time)) >= DATE_FORMAT(DATE_SUB(CURRENT_DATE(), INTERVAL #{offsetMonths} MONTH), '%Y-%m-01')
AND h.house_province IS NOT NULL AND h.house_province != '' AND h.house_district IS NOT NULL AND h.house_district != '' GROUP BY h.house_province, h.house_city, h.house_district ORDER BY salesAmount DESC, transactionCount DESC LIMIT #{limit}
